fn safe_count(value: Option<f64>) -> Option<u64> {
    value
        .filter(|value| {
            value.is_finite()
                && *value >= 0.0
                && *value <= 9_007_199_254_740_991.0
                && value.fract() == 0.0
        })
        .map(|value| value as u64)
}
